using FsCheck.Fluent;
namespace Atm.Tests;
public class Couverture(Xunit.Abstractions.ITestOutputHelper o)
{
    [Fact]
    public void Statuts()
    {
        var c = Generateurs.Compte().Generator.Sample(200, 10, 1000);
        var s = Generateurs.Stock().Generator.Sample(200, 10, 1000);
        var b = Generateurs.Bloquee().Generator.Sample(200, 10, 1000);
        var m = Generateurs.Montant().Generator.Sample(200, 10, 1000);
        var d = Generateurs.Depot().Generator.Sample(200, 10, 1000);
        var w = Enumerable.Range(0, 1000).Select(i => new CashMachine(new MoneyDispenser(s[i].Valeur, b[i].Valeur)).Execute(c[i].Valeur, new Operation.Withdraw(m[i].Valeur)).Status);
        var dd = Enumerable.Range(0, 1000).Select(i => new CashMachine(new MoneyDispenser(s[i].Valeur, b[i].Valeur)).Execute(c[i].Valeur, new Operation.Deposit(d[i].Valeur)).Status);
        o.WriteLine(string.Join(", ", w.GroupBy(x => x).Select(g => $"{g.Key}:{g.Count()}")));
